import mneimport osfrom glob import globfrom mne_bids import (BIDSPath,write_raw_bids)'''run first to rename files into BIDS format for later use'''subPath        = r'Z:\RAW_DATA\SWITCH\beh-eeg-switch\study_2026' # location of raw data: each subject is one folder in the host study_2026 foldersubFolders     = glob(os.path.join(subPath, 'sub-2*'))savePath       = r'D:\switch_coherence_data' # make a new location for BIDS named data to be saved. Will be the data path going forward# loop to go in each folder that looks for all files in the eeg folder for each subfor sub in subFolders:        eegFiles   = glob(os.path.join(sub,'eeg', '*.vhdr'))    subName    = sub.split('/')[-1]    subName    = subName.split('-')[-1]    session    = subName.split('S')[0]    subName    = subName.split('S')[1]    if len(subName) == 1:        subName    = '00'+subName    elif len(subName) == 2:        subName    = '0'+subName        for file in eegFiles:                       raw       = mne.io.read_raw_brainvision(file)                RunType   = file.split('/')[-1]        if ('target_training' in RunType) or ('TT' in RunType):            RunType   = 'TargetTraining'            RunNumber = 1                    elif ('Mock' in RunType):              RunNumber = file.split('_Run')[-1]            RunNumber = RunNumber.split('_2')[0]                        RunType   = 'Mock'#RunType.split('_')[0]               elif ('Main' in RunType):            RunNumber = file.split('_Run')[-1]            RunNumber = RunNumber.split('_2')[0]                         RunType   = 'Main'                    bids_path   = BIDSPath(root  = savePath,                             subject = subName,                             session = session,                             task    = RunType,                             run     = int(RunNumber),                             extension ='eeg',                              datatype  ='eeg')                write_raw_bids(raw, bids_path=bids_path, overwrite=True)       